"""Figures for the report. Every one is regenerated by `eval.run_eval`."""

from __future__ import annotations

from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
from sklearn.metrics import roc_curve  # noqa: E402

from iudbms.contract import feature_index  # noqa: E402

__all__ = ["write_figures"]

C_FULL, C_S1, C_ID = "#c0392b", "#e67e22", "#7f8c8d"
C_ONSET, C_ACT = "#27ae60", "#2980b9"


def _timeline(ax, s, result, title):
    """One device session: both stage scores, the onset, and the action."""
    t = s.t
    ax.plot(t, result.stage1[s.sid], lw=1.3, color=C_S1,
            label="Stage 1 (memoryless)")
    ax.plot(t, result.stage2[s.sid], lw=2.1, color=C_FULL,
            label="Stage 2 (LSTM, P(malicious))")
    ax.axhline(result.threshold, ls="--", c="k", lw=1,
               label=f"learned threshold {result.threshold:.3f}")
    if s.onset is not None:
        ax.axvline(s.onset, ls=":", c=C_ONSET, lw=2,
                   label=f"attack onset {s.onset:.0f}s")

    # first window where the 4-of-6 gate would have fired
    above = (np.asarray(result.stage2[s.sid]) >= result.threshold).astype(int)
    fired = None
    for i in range(len(above)):
        if above[max(0, i - 5):i + 1].sum() >= 4:
            fired = float(t[i]) + 1.0
            break
    if fired is not None:
        ax.axvline(fired, ls="-", c=C_ACT, lw=2,
                   label=f"enforcement {fired:.0f}s")
    ax.set_ylim(-0.03, 1.03)
    ax.set_xlabel("time since enumeration (s)")
    ax.set_ylabel("score")
    ax.set_title(title, fontsize=10.5)
    ax.legend(fontsize=7.5, loc="upper left", framealpha=.92)
    return fired


def write_figures(out: Path, full, s1_only, modality, test, y_true=None,
                  p_full=None, p_s1=None) -> list[Path]:
    written = []

    # --- 1. detection rate by attack class -------------------------------
    profiles = [p for p, v in sorted(full.per_profile.items()) if v["label"] == 1]
    if profiles:
        x = np.arange(len(profiles))
        fig, ax = plt.subplots(figsize=(9, 4.6))
        ax.bar(x - 0.27, [full.per_profile[p]["detect_rate"] for p in profiles], 0.27,
               label="IUDBMS (S1+S2)", color=C_FULL)
        ax.bar(x, [s1_only.per_profile.get(p, {}).get("detect_rate", 0) for p in profiles],
               0.27, label="Stage 1 only", color=C_S1)
        ax.bar(x + 0.27, [0.0] * len(profiles), 0.27,
               label="Identity whitelist", color=C_ID)
        for i, p in enumerate(profiles):
            ax.text(i - 0.27, full.per_profile[p]["detect_rate"] + 0.02,
                    f"n={full.per_profile[p]['n']}", ha="center", fontsize=7.5,
                    color="#555")
        ax.set_xticks(x)
        ax.set_xticklabels(profiles, fontsize=9, rotation=12)
        ax.set_ylabel("session detection rate")
        ax.set_ylim(0, 1.12)
        ax.set_title("Detection rate by attack class (held-out test sessions)")
        ax.legend(fontsize=8, loc="lower right")
        fig.tight_layout()
        p = out / "detection_by_class.png"
        fig.savefig(p, dpi=150); plt.close(fig); written.append(p)

    # --- 2. per-modality ablation (pillar N1) ----------------------------
    if modality:
        names = list(modality)
        fig, ax = plt.subplots(figsize=(7, 4.4))
        vals = [modality[m].window["auc"] for m in names]
        ax.bar(names, vals, color="#2980b9", width=0.55)
        ax.axhline(full.window["auc"], ls="--", c=C_FULL, lw=1.6,
                   label=f"all modalities fused  AUC={full.window['auc']:.4f}")
        for i, v in enumerate(vals):
            ax.text(i, v + 0.012, f"{v:.4f}", ha="center", fontsize=8)
        ax.set_ylabel("window ROC-AUC")
        ax.set_ylim(0.4, 1.06)
        ax.set_title("Single-modality ablation — does fusion earn its keep? (N1)")
        ax.legend(fontsize=8, loc="lower left")
        fig.tight_layout()
        p = out / "modality_ablation.png"
        fig.savefig(p, dpi=150); plt.close(fig); written.append(p)

    # --- 3. ROC ----------------------------------------------------------
    if y_true is not None and p_full is not None:
        fig, ax = plt.subplots(figsize=(6, 5.2))
        for name, pr, auc, c in (("Stage 1 only", p_s1, s1_only.window["auc"], C_S1),
                                 ("IUDBMS (S1+S2)", p_full, full.window["auc"], C_FULL)):
            if pr is None:
                continue
            fpr, tpr, _ = roc_curve(y_true, pr)
            ax.plot(fpr, tpr, lw=2, color=c, label=f"{name}  AUC={auc:.4f}")
        ax.plot([0, 1], [0, 1], "k--", lw=.8, label="identity-based defence (chance)")
        ax.set_xlabel("false positive rate (benign windows)")
        ax.set_ylabel("true positive rate (malicious windows)")
        ax.set_title("Window-level ROC, held-out test set")
        ax.legend(fontsize=8, loc="lower right")
        fig.tight_layout()
        p = out / "roc.png"
        fig.savefig(p, dpi=150); plt.close(fig); written.append(p)

    # --- 4. session timelines: the easy case and the hard one ------------
    if full.stage2:
        picks = []
        for profile in ("staged_delay", "mimicry"):
            cand = [s for s in test if s.profile == profile and s.sid in full.stage2]
            if cand:
                picks.append((profile, cand[0]))
        if picks:
            fig, axes = plt.subplots(len(picks), 1, figsize=(11, 4.0 * len(picks)))
            axes = np.atleast_1d(axes)
            titles = {
                "staged_delay": "Staged BadUSB — human-like typing, then injection. "
                                "Stage 1 misses it; the transition is what gives it away.",
                "mimicry": "Mimicry — human-calibrated timing, replayed script. "
                           "Detected only as payload-sequence novelty decays.",
            }
            for ax, (profile, s) in zip(axes, picks):
                _timeline(ax, s, full, titles[profile])
            fig.tight_layout()
            p = out / "session_timelines.png"
            fig.savefig(p, dpi=150); plt.close(fig); written.append(p)

    # --- 5. what makes mimicry visible at all ----------------------------
    mim = [s for s in test if s.profile == "mimicry" and s.sid in full.stage2]
    ben = [s for s in test if s.profile == "keyboard"]
    if mim and ben:
        i = feature_index("payload_seq_novelty")
        fig, ax = plt.subplots(figsize=(8, 4.2))
        edges = np.arange(0, 90, 5)
        for group, label, colour in ((ben, "benign keyboard", C_ONSET),
                                     (mim, "mimicry (post-onset)", C_FULL)):
            xs, ys = [], []
            for lo, hi in zip(edges, edges[1:]):
                vals = []
                for s in group:
                    m = (s.t >= lo) & (s.t < hi)
                    if group is mim:
                        m &= s.y == 1
                    vals.extend(s.X[m][:, i].tolist())
                if len(vals) >= 20:
                    xs.append((lo + hi) / 2); ys.append(float(np.mean(vals)))
            ax.plot(xs, ys, lw=2, marker="o", ms=4, color=colour, label=label)
        ax.set_xlabel("window position in session (s)")
        ax.set_ylabel("payload sequence novelty")
        ax.set_ylim(0, 1.05)
        ax.set_title("Why mimicry is detectable: a replayed script exhausts its own\n"
                     "payload transitions, while a human keeps producing new ones",
                     fontsize=10.5)
        ax.legend(fontsize=8, loc="lower left")
        ax.text(0.98, 0.06, "compared at matched window positions,\n"
                            "so this is behaviour and not session position",
                transform=ax.transAxes, ha="right", fontsize=7.5, color="#666")
        fig.tight_layout()
        p = out / "seq_novelty_decay.png"
        fig.savefig(p, dpi=150); plt.close(fig); written.append(p)

    return written
